CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lessons(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS student_work(student_code TEXT NOT NULL,stage INTEGER NOT NULL,answer TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(student_code,stage));
CREATE TABLE IF NOT EXISTS revisions(id INTEGER PRIMARY KEY AUTOINCREMENT,student_code TEXT NOT NULL,stage INTEGER NOT NULL,answer TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scores(student_code TEXT NOT NULL,period TEXT NOT NULL,values_json TEXT NOT NULL,PRIMARY KEY(student_code,period));
CREATE TABLE IF NOT EXISTS routes(student_code TEXT PRIMARY KEY,task TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS works(id TEXT PRIMARY KEY,data TEXT NOT NULL);
